//! NearbyEnemies — brute-force O(nÂ²) neighbour rebuild every tick.
//!
//! Replaces the incremental SpatialHash/spatialty pipeline. After movement has
//! updated positions, this system:
//!   1. Collects all living unit positions, owners, and moved-flags.
//!   2. For each unit, scans every other unit and collects enemies within
//!      COMBAT_RANGE (with owner filter).
//!   3. Writes/updates NearbyEnemies for every unit.
//!   4. Sets `attacking` only on movers that have at least one enemy nearby.
//!
//! The O(nÂ²) cost is acceptable at game scale (tens to low hundreds of units).
//! Each pair check is ~4 FP ops â no HashMap lookups, no Vec allocations,
//! no pointer chasing.

use crate::game::components::*;
use crate::game::constants::COMBAT_RANGE_SQ;
use hecs::Entity;

pub fn run(world: &mut hecs::World) {
    // 1. Collect all living unit data in one ECS query.
    let units: Vec<(Entity, UnitPosition, String, bool)> = world
        .query::<(Entity, &UnitPosition, &UnitOwner, &UnitFlags)>()
        .iter()
        .map(|(e, pos, owner, flags)| {
            (e, *pos, owner.player_id.clone(), flags.moved)
        })
        .collect();

    let n = units.len();
    if n == 0 {
        return;
    }

    // 2. For each unit, find enemies within COMBAT_RANGE.
    for i in 0..n {
        let (entity_i, pos_i, owner_i, moved_i) = &units[i];

        let enemies: Vec<Entity> = (0..n)
            .filter(|&j| {
                if j == i {
                    return false;
                }
                // Different owner
                if owner_i == &units[j].2 {
                    return false;
                }
                // Within combat range (squared distance, avoids sqrt)
                let dx = pos_i.x - units[j].1.x;
                let dy = pos_i.y - units[j].1.y;
                dx * dx + dy * dy < COMBAT_RANGE_SQ
            })
            .map(|j| units[j].0)
            .collect();

        // 3. Write/update NearbyEnemies for this unit.
        let has_nearby = world.get::<&NearbyEnemies>(*entity_i).is_ok();
        if has_nearby {
            if let Ok((nb,)) = world.query_one_mut::<(&mut NearbyEnemies,)>(*entity_i) {
                nb.entities = enemies.clone();
                nb.initialized = true;
            }
        } else {
            let _ = world.insert(
                *entity_i,
                (NearbyEnemies {
                    entities: enemies.clone(),
                    initialized: true,
                },),
            );
        }

        // 4. Set `attacking` ONLY for movers: a unit that moved and is now
        //    within COMBAT_RANGE of an enemy. This covers both "moved toward
        //    enemy" and "moved into enemy combat radius". Stationary units
        //    keep whatever state combat left them in.
        if *moved_i {
            let has_enemies = !enemies.is_empty();
            if let Ok((flags,)) = world.query_one_mut::<(&mut UnitFlags,)>(*entity_i) {
                flags.attacking = has_enemies;
            }
        }
    }
}

