arguments.new_string:
//! NearbyEnemies — grid-based neighbour rebuild every tick.
//!
//! Uses a coarse spatial grid (cell_size = COMBAT_RANGE) so each unit only
//! checks the ~1-5 entities in its 3×3 cell neighbourhood instead of every
//! other unit. No HashMap-based SpatialHash, no incremental maintenance.
//!
//! Pipeline:
//!   1. Build grid index: entity → cell (one pass, O(n)).
//!   2. For each unit, query 3×3 cell neighbourhood, filter enemies within
//!      COMBAT_RANGE, write NearbyEnemies and `attacking` flag.
//!
//! Complexity: O(n × c) where c ≈ entities per 3×3 cell neighbourhood.
//! At game scale (500 units on 200×200 grid), c is very small (~2-3), so
//! this is ~150-250 distance checks vs 250,000 for brute-force O(n²).

use std::collections::HashMap;

use crate::game::components::*;
use crate::game::constants::COMBAT_RANGE;
use crate::game::constants::COMBAT_RANGE_SQ;
use hecs::Entity;

/// Coarse spatial grid: cell → list of (entity, position) pairs.
/// Cell size equals COMBAT_RANGE so the 3×3 query always covers the
/// full combat radius (diagonal of 3 cells = ~3.46, well beyond range 2.0).
struct GridIndex {
    data: HashMap<(i32, i32), Vec<(Entity, UnitPosition)>>,
}

impl GridIndex {
    fn new() -> Self {
        Self {
            data: HashMap::new(),
        }
    }

    fn insert(&mut self, e: Entity, pos: UnitPosition) {
        let c = cell_for(pos);
        self.data.entry(c).or_default().push((e, pos));
    }

    /// Query the 3×3 neighbourhood centred on (cx, cy).
    fn query_3x3_into(&self, cx: i32, cy: i32, out: &mut Vec<(Entity, UnitPosition)>) {
        for dx in -1..=1 {
            for dy in -1..=1 {
                if let Some(data) = self.data.get(&(cx + dx, cy + dy)) {
                    out.extend_from_slice(data);
                }
            }
        }
    }
}

#[inline]
fn cell_for(pos: UnitPosition) -> (i32, i32) {
    (
        (pos.x / COMBAT_RANGE).floor() as i32,
        (pos.y / COMBAT_RANGE).floor() as i32,
    )
}

pub fn run(world: &mut hecs::World) {
    // 1. Collect all living unit data in one ECS query.
    let units: Vec<(Entity, UnitPosition, String)> = world
        .query::<(Entity, &UnitPosition, &UnitOwner)>()
        .iter()
        .map(|(e, pos, owner)| (e, *pos, owner.player_id.clone()))
        .collect();

    let n = units.len();
    if n == 0 {
        return;
    }

    // 2. Build grid index.
    let mut grid = GridIndex::new();
    for &(e, pos, _) in &units {
        grid.insert(e, pos);
    }

    // Reuse buffers to avoid per-unit allocation.
    let mut neighbours = Vec::with_capacity(32);
    let mut enemies = Vec::with_capacity(16);

    // 3. For each unit, query 3×3 neighbourhood and build NearbyEnemies.
    for &(entity, pos, ref owner) in &units {
        // Query grid neighbourhood.
        let c = cell_for(pos);
        neighbours.clear();
        grid.query_3x3_into(c.0, c.1, &mut neighbours);

        // Filter: different owner, within combat range.
        enemies.clear();
        for &(ne, npos) in &neighbours {
            if ne == entity {
                continue;
            }
            // Find owner of neighbour (linear scan is fine, small n).
            let no = match units.iter().find(|&&(e, _, _)| e == ne) {
                Some((_, _, o)) => o,
                None => continue,
            };
            if *owner == *no {
                continue;
            }
            let dx = pos.x - npos.x;
            let dy = pos.y - npos.y;
            if dx * dx + dy * dy < COMBAT_RANGE_SQ {
                enemies.push(ne);
            }
        }

        // Write/update NearbyEnemies.
        if let Ok((nb,)) = world.query_one_mut::<(&mut NearbyEnemies,)>(entity) {
            nb.entities = std::mem::take(&mut enemies);
            nb.initialized = true;
            enemies = Vec::with_capacity(16); // restore capacity
        } else {
            let _ = world.insert(
                entity,
                (NearbyEnemies {
                    entities: enemies.drain(..).collect(),
                    initialized: true,
                },),
            );
        }

        // Set `attacking` flag for movers only.
        if let Ok((moved,)) = world.get::<&UnitFlags>(entity) {
            if moved.moved {
                if let Ok((flags,)) = world.query_one_mut::<(&mut UnitFlags,)>(entity) {
                    flags.attacking = !enemies.is_empty();
                }
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::config::CityUpgradeSettings;
    use crate::game::world_ext::WorldExt;

    fn setup() -> (hecs::World, hecs::Entity) {
        let mut world = hecs::World::new();
        let entity = world.spawn_world(
            vec![vec![crate::game::unit::Terrain::Plains; 200]; 200],
            200,
            200,
            CityUpgradeSettings::default(),
            std::collections::HashMap::new(),
            Vec::new(),
        );
        (world, entity)
    }

    /// Spawn a unit with the given owner, position and moved flag.
    fn make_unit(
        world: &mut hecs::World,
        owner: &str,
        x: f32,
        y: f32,
        moved: bool,
    ) -> hecs::Entity {
        world.spawn((
            UnitOwner {
                player_id: owner.to_string(),
            },
            UnitPosition { x, y },
            UnitFlags {
                moved,
                ..UnitFlags::default()
            },
        ))
    }

    #[test]
    fn initializes_new_spawns_and_sees_each_other() {
        let (mut world, _world_entity) = setup();
        let a = make_unit(&mut world, "P1", 10.0, 10.0, false);
        let b = make_unit(&mut world, "P2", 10.5, 10.5, false);
        run(&mut world);

        let nearby_a = world.get::<&NearbyEnemies>(a).unwrap();
        assert!(nearby_a.initialized);
        assert!(
            nearby_a.entities.contains(&b),
            "A should see enemy B"
        );

        let nearby_b = world.get::<&NearbyEnemies>(b).unwrap();
        assert!(nearby_b.initialized);
        assert!(nearby_b.entities.contains(&a), "B should see enemy A");
    }

    #[test]
    fn ignores_same_owner() {
        let (mut world, _world_entity) = setup();
        let a = make_unit(&mut world, "P1", 10.0, 10.0, false);
        let b = make_unit(&mut world, "P1", 10.5, 10.5, false);
        run(&mut world);

        let nearby_a = world.get::<&NearbyEnemies>(a).unwrap();
        assert!(
            !nearby_a.entities.contains(&b),
            "same-owner must be excluded"
        );
        let nearby_b = world.get::<&NearbyEnemies>(b).unwrap();
        assert!(
            !nearby_b.entities.contains(&a),
            "same-owner must be excluded"
        );
    }

    #[test]
    fn mover_sets_attacking_with_enemy_nearby() {
        let (mut world, _world_entity) = setup();
        // Stationary defender (moved=false).
