//! NearbyEnemies — grid-based incremental neighbour rebuild.
//!
//! Replaces the brute-force O(n²) approach. Uses a coarse spatial grid
//! (cell_size = COMBAT_RANGE) so that only movers and their immediate
//! neighbours need their NearbyEnemies rebuilt each tick.
//!
//! Pipeline:
//!   1. Build grid index: entity → cell (O(n), one pass).
//!   2. Identify affected entities:
//!      - Every mover (its list may have changed).
//!      - Every enemy in cells adjacent to a mover's new position
//!        (they may now see / no longer see the mover).
//!   3. For each affected entity, query the 3×3 cell neighbourhood
//!      to rebuild NearbyEnemies and set `attacking` flag.
//!
//! At game scale (~200 movers out of 500 units) this is much cheaper
//! than rebuilding all 500 lists every tick.

use std::collections::HashMap;

use crate::game::components::*;
use crate::game::constants::COMBAT_RANGE;
use crate::game::constants::COMBAT_RANGE_SQ;
use hecs::Entity;

/// Coarse spatial grid: cell → list of entities in that cell.
/// Cell size equals COMBAT_RANGE so the 3×3 query always covers the
/// full combat radius.
struct GridIndex {
    cells: HashMap<(i32, i32), Vec<Entity>>,
    /// cell → (entity, position) for fast rebuild
    cell_data: HashMap<(i32, i32), Vec<(Entity, UnitPosition)>>,
}

impl GridIndex {
    fn new() -> Self {
        Self {
            cells: HashMap::new(),
            cell_data: HashMap::new(),
        }
    }

    fn insert(&mut self, e: Entity, pos: UnitPosition) {
        let c = cell_for(pos);
        self.cells.entry(c).or_default().push(e);
        self.cell_data.entry(c).or_default().push((e, pos));
    }

    /// Query the 3×3 neighbourhood centred on (cx, cy).
    /// Returns all (entity, position) tuples in adjacent cells.
    fn query_3x3(&self, cx: i32, cy: i32) -> &Vec<(Entity, UnitPosition)> {
        // Return a combined view; we merge cells inline in the caller
        &vec![]
    }

    fn query_3x3_into(&self, cx: i32, cy: i32, out: &mut Vec<(Entity, UnitPosition)>) {
        for dx in -1..=1 {
            for dy in -1..=1 {
                if let Some(data) = self.cell_data.get(&(cx + dx, cy + dy)) {
                    out.extend_from_slice(data);
                }
            }
        }
    }
}

#[inline]
fn cell_for(pos: UnitPosition) -> (i32, i32) {
    (
        (pos.x / COMBAT_RANGE).floor() as i32,
        (pos.y / COMBAT_RANGE).floor() as i32,
    )
}

/// Collect all entities that need their NearbyEnemies rebuilt this tick.
fn affected_entities(
    units: &[(Entity, UnitPosition, String)],
    grid: &GridIndex,
) -> Vec<Entity> {
    let mut affected = Vec::new();
    let mut seen = std::collections::HashSet::new();

    for &(e, pos, ref _owner) in units {
        // Find the 3×3 neighbourhood
        let c = cell_for(pos);
        let mut neighbours = Vec::new();
        grid.query_3x3_into(c.0, c.1, &mut neighbours);

        // Check for any enemies nearby
        let has_enemy_nearby = neighbours
            .iter()
            .any(|&((ne, _),)| ne != e); // simplified; actual check below

        if has_enemy_nearby || seen.contains(&e) {
            continue; // already marked
        }

        affected.push(e);
        seen.insert(e);

        // Also mark all neighbours as affected
        for &(ne, _) in &neighbours {
            if ne != e {
                if seen.insert(ne) {
                    affected.push(ne);
                }
            }
        }
    }

    affected
}

pub fn run(world: &mut hecs::World) {
    // 1. Collect all living unit data in one ECS query.
    let units: Vec<(Entity, UnitPosition, String)> = world
        .query::<(Entity, &UnitPosition, &UnitOwner)>()
        .iter()
        .map(|(e, pos, owner)| (e, *pos, owner.player_id.clone()))
        .collect();

    let n = units.len();
    if n == 0 {
        return;
    }

    // 2. Build grid index.
    let mut grid = GridIndex::new();
    for &(e, pos, _) in &units {
        grid.insert(e, pos);
    }

    // 3. Identify movers and their affected neighbours.
    let movers: Vec<Entity> = world
        .query::<(Entity, &UnitFlags)>()
        .iter()
        .filter(|(_, f)| f.moved)
        .map(|(e, _)| e)
        .collect();

    // Affected = movers + any enemy in a cell adjacent to a mover.
    let mut affected: std::collections::HashSet<Entity> = movers.iter().copied().collect();
    for m in &movers {
        if let Some((_, pos, _)) = units.iter().find(|&&(e, _, _)| e == *m) {
            let c = cell_for(pos);
            let mut neighbours = Vec::new();
            grid.query_3x3_into(c.0, c.1, &mut neighbours);
            for &(ne, _) in &neighbours {
                affected.insert(ne);
            }
        }
    }

    // If no units moved, nothing to update.
    if affected.is_empty() {
        return;
    }

    // 4. Rebuild NearbyEnemies for each affected entity.
    let mut neighbours = Vec::with_capacity(32);
    for ae in &affected {
        let (pos, owner) = match units.iter().find(|&&(e, _, _)| e == *ae) {
            Some((_, p, o)) => (*p, o.clone()),
            None => continue,
        };

        let c = cell_for(pos);
        neighbours.clear();
        grid.query_3x3_into(c.0, c.1, &mut neighbours);

        let enemies: Vec<Entity> = neighbours
            .iter()
            .filter_map(|&(ne, npos)| {
                if ne == *ae {
                    return None;
                }
                let (_, no) = units.iter().find(|&&(e, _, _)| e == ne)?;
                if owner == no {
                    return None;
                }
                let dx = pos.x - npos.x;
                let dy = pos.y - npos.y;
                (dx * dx + dy * dy < COMBAT_RANGE_SQ).then_some(ne)
            })
            .collect();

        // Write/update NearbyEnemies.
        if let Ok((nb,)) = world.query_one_mut::<(&mut NearbyEnemies,)>(*ae) {
            nb.entities = enemies.clone();
            nb.initialized = true;
        } else {
            let _ = world.insert(
                *ae,
                (NearbyEnemies {
                    entities: enemies.clone(),
                    initialized: true,
                },),
            );
        }

        // Set `attacking` flag.
        if movers.contains(ae) {
            if let Ok((flags,)) = world.query_one_mut::<(&mut UnitFlags,)>(*ae) {
                flags.attacking = !enemies.is_empty();
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::config::CityUpgradeSettings;
    use crate::game::world_ext::WorldExt;

    fn setup() -> (hecs::World, hecs::Entity) {
        let mut world = hecs::World::new();
        let entity = world.spawn_world(
            vec![vec![crate::game::unit::Terrain::Plains; 200]; 200],
            200,
            200,
            CityUpgradeSettings::default(),
            std::collections::HashMap::new(),
            Vec::new(),
        );
        (world, entity)
    }

    /// Spawn a unit with the given owner, position and moved flag.
    fn make_unit(
        world: &mut hecs::World,
        owner: &str,
        x: f32,
        y: f32,
        moved: bool,
    ) -> hecs::Entity {
        world.spawn((
            UnitOwner {
                player_id: owner.to_string(),
            },
            UnitPosition { x, y },
            UnitFlags {
                moved,
                ..UnitFlags::default()
            },
        ))
    }

    #[test]
    fn initializes_new_spawns_and_sees_each_other() {
        let (mut world, _world_entity) = setup();
        let a = make_unit(&mut world, "P1", 10.0, 10.0, true);
        let b = make_unit(&mut world, "P2", 10.5, 10.5, true);
        run(&mut world);

        let nearby_a = world.get::<&NearbyEnemies>(a).unwrap();
        assert!(nearby_a.initialized);
        assert!(
            nearby_a.entities.contains(&b),
            "A should see enemy B"
        );

        let nearby_b = world.get::<&NearbyEnemies>(b).unwrap();
        assert!(nearby_b.initialized);
        assert!(nearby_b.entities.contains(&a), "B should see enemy A");
    }

    #[test]
    fn ignores_same_owner() {
        let (mut world, _world_entity) = setup();
        let a = make_unit(&mut world, "P1", 10.0, 10.0, true);
        let b = make_unit(&mut world, "P1", 10.5, 10.5, true);
        run(&mut world);

        let nearby_a = world.get::<&NearbyEnemies>(a).unwrap();
        assert!(
            !nearby_a.entities.contains(&b),
            "same-owner must be excluded"
        );
        let nearby_b = world.get::<&NearbyEnemies>(b).unwrap();
        assert!(
            !nearby_b.entities.contains(&a),
            "same-owner must be excluded"
        );
    }

    #[test]
    fn mover_sets_attacking_with_enemy_nearby() {
        let (mut world, _world_entity) = setup();
        // Stationary defender (moved=false).
        let b = make_unit(&mut world, "P2", 10.5, 10.5, false);
        // Mover advancing toward B (moved=true).
        let a = make_unit(&mut world, "P1", 10.0, 10.0, true);
        run(&mut world);

        assert!(
            world.get::<&UnitFlags>(a).unwrap().attacking,
            "mover with a nearby enemy must have attacking=true"
        );
        let nearby_b = world.get::<&NearbyEnemies>(b).unwrap();
        assert!(
            nearby_b.entities.contains(&a),
            "stationary B should see mover A"
        );
    }

    #[test]
    fn mover_clears_attacking_when_no_enemy_nearby() {
        let (mut world, _world_entity) = setup();
        // Mover at a far distance from anyone.
        let a = make_unit(&mut world, "P1", 0.0, 0.0, true);
        let b = make_unit(&mut world, "P2", 100.0, 100.0, false);
        run(&mut world);

        assert!(
            !world.get::<&UnitFlags>(a).unwrap().attacking,
            "mover far from enemies should have attacking=false"
        );
    }

    #[test]
    fn stationary_defender_does_not_become_attacker() {
        let (mut world, _world_entity) = setup();
        let b = make_unit(&mut world, "P2", 10.5, 10.5, false);
        let a = make_unit(&mut world, "P1", 10.0, 10.0, true);
        run(&mut world);

        assert!(
            !world.get::<&UnitFlags>(b).unwrap().attacking,
            "stationary defender must NOT become an attacker"
        );
        assert!(
            !world.get::<&NearbyEnemies>(b).unwrap().entities.is_empty(),
            "B should see mover A"
        );
    }

    #[test]
    fn two_nearby_movers_see_each_other_and_attack() {
        let (mut world, _world_entity) = setup();
        let a = make_unit(&mut world, "P1", 10.0, 10.0, true);
        let b = make_unit(&mut world, "P2", 10.5, 10.5, true);
        run(&mut world);

        assert!(world
            .get::<&NearbyEnemies>(a)
            .unwrap()
            .entities
            .contains(&b));
        assert!(world
            .get::<&NearbyEnemies>(b)
            .unwrap()
            .entities
            .contains(&a));
        assert!(world.get::<&UnitFlags>(a).unwrap().attacking);
        assert!(world.get::<&UnitFlags>(b).unwrap().attacking);
    }

    #[test]
    fn three_owners_all_see_each_other() {
        let (mut world, _world_entity) = setup();
        let a = make_unit(&mut world, "P1", 10.0, 10.0, true);
        let b = make_unit(&mut world, "P2", 10.5, 10.5, true);
        let cc = make_unit(&mut world, "P3", 10.2, 10.2, true);
        run(&mut world);

        let na = world.get::<&NearbyEnemies>(a).unwrap();
        assert!(na.entities.contains(&b) && na.entities.contains(&cc));
        let nb = world.get::<&NearbyEnemies>(b).unwrap();
        assert!(nb.entities.contains(&a) && nb.entities.contains(&cc));
        let nc = world.get::<&NearbyEnemies>(cc).unwrap();
        assert!(nc.entities.contains(&a) && nc.entities.contains(&b));
    }

    #[test]
    fn dense_cluster_filters_self_and_allies() {
        let (mut world, _world_entity) = setup();
        let p1a = make_unit(&mut world, "P1", 10.0, 10.0, true);
        let p1b = make_unit(&mut world, "P1", 10.1, 10.1, true);
        let p1c = make_unit(&mut world, "P1", 10.2, 10.2, true);
        let p2a = make_unit(&mut world, "P2", 10.3, 10.3, true);
        let p2b = make_unit(&mut world, "P2", 10.4, 10.4, true);
        run(&mut world);

        for (unit, label) in [(&p1a, "P1A"), (&p1b, "P1B"), (&p1c, "P1C")] {
            let nb = world.get::<&NearbyEnemies>(*unit).unwrap();
            assert_eq!(
                nb.entities.len(),
                2,
                "{} should see exactly 2 P2 enemies",
                label
            );
            assert!(nb.entities.contains(&p2a) && nb.entities.contains(&p2b));
            assert!(
                !nb.entities.contains(unit),
                "{} must not see itself",
                label
            );
        }
        for (unit, label) in [(&p2a, "P2A"), (&p2b, "P2B")] {
            let nb = world.get::<&NearbyEnemies>(*unit).unwrap();
            assert_eq!(
                nb.entities.len(),
                3,
                "{} should see 3 P1 enemies",
                label
            );
        }
    }

    #[test]
    fn empty_world_does_not_panic() {
        let (mut world, _world_entity) = setup();
        run(&mut world);
    }

    #[test]
    fn units_beyond_combat_range_not_seen() {
        let (mut world, _world_entity) = setup();
        let a = make_unit(&mut world, "P1", 0.0, 0.0, true);
        let b = make_unit(&mut world, "P2", 10.0, 10.0, true);
        run(&mut world);

        let nearby_a = world.get::<&NearbyEnemies>(a).unwrap();
        assert!(nearby_a.entities.is_empty(), "far units should not be in NearbyEnemies");
        let nearby_b = world.get::<&NearbyEnemies>(b).unwrap();
        assert!(nearby_b.entities.is_empty(), "far units should not be in NearbyEnemies");
    }
}

