//! NearbyEnemies — grid-based neighbour rebuild every tick.
//!
//! Uses a coarse spatial grid (cell_size = COMBAT_RANGE = 2.0) so each unit only
//! checks the ~1-5 entities in its 3×3 cell neighbourhood instead of every
//! other unit. No HashMap-based SpatialHash, no incremental maintenance.
//!
//! Pipeline:
//!   1. Build grid index: entity → cell (one pass, O(n)).
//!   2. For each unit, query 3×3 cell neighbourhood, filter enemies within
//!      COMBAT_RANGE, write NearbyEnemies and `attacking` flag.
//!
//! Complexity: O(n × c) where c ≈ entities per 3×3 cell neighbourhood.
//! At game scale (500 units on 200×200 grid), c is very small (~2-3), so
//! this is ~150-250 distance checks vs 250,000 for brute-force O(n²).

use std::collections::HashMap;

use crate::game::components::*;
use crate::game::constants::COMBAT_RANGE_SQ;
use hecs::Entity;

/// Cell size equals COMBAT_RANGE (sqrt(4.0) = 2.0).
const CELL_SIZE: f32 = 2.0;

/// Coarse spatial grid: cell → list of (entity, position) pairs.
/// Cell size equals COMBAT_RANGE so the 3×3 query always covers the
/// full combat radius.
struct GridIndex {
    data: HashMap<(i32, i32), Vec<(Entity, UnitPosition)>>,
}

impl GridIndex {
    fn new() -> Self {
        Self {
            data: HashMap::new(),
        }
    }

    fn insert(&mut self, e: Entity, pos: UnitPosition) {
        let c = cell_for(pos);
        self.data.entry(c).or_default().push((e, pos));
    }

    /// Query the 3×3 neighbourhood centred on (cx, cy).
    fn query_3x3_into(&self, cx: i32, cy: i32, out: &mut Vec<(Entity, UnitPosition)>) {
        for dx in -1..=1 {
            for dy in -1..=1 {
                if let Some(data) = self.data.get(&(cx + dx, cy + dy)) {
                    out.extend_from_slice(data);
                }
            }
        }
    }
}

#[inline]
fn cell_for(pos: UnitPosition) -> (i32, i32) {
    (
        (pos.x / CELL_SIZE).floor() as i32,
        (pos.y / CELL_SIZE).floor() as i32,
    )
}

pub fn run(world: &mut hecs::World) {
    // 1. Collect all living unit data in one ECS query.
    let units: Vec<(Entity, UnitPosition, String, bool)> = world
        .query::<(Entity, &UnitPosition, &UnitOwner, &UnitFlags)>()
        .iter()
        .map(|(e, pos, owner, flags)| (e, *pos, owner.player_id.clone(), flags.moved))
        .collect();

    let n = units.len();
    if n == 0 {
        return;
    }

    // 2. Build grid index.
    let mut grid = GridIndex::new();
    for &(e, pos, _, _) in &units {
        grid.insert(e, pos);
    }

    // Reuse buffers to avoid per-unit allocation.
    let mut neighbours = Vec::with_capacity(32);
    let mut enemies = Vec::with_capacity(16);

    // 3. For each unit, query 3×3 neighbourhood and build NearbyEnemies.
    for &(entity, pos, ref owner, is_moved) in &units {
        // Query grid neighbourhood.
        let c = cell_for(pos);
        neighbours.clear();
        grid.query_3x3_into(c.0, c.1, &mut neighbours);

        // Filter: different owner, within combat range.
        enemies.clear();
        for &(ne, npos) in &neighbours {
            if ne == entity {
                continue;
            }
            // Find owner of neighbour (linear scan is fine, small n).
            let no = match units.iter().find(|&&(e, _, _, _)| e == ne) {
                Some((_, _, o, _)) => o,
                None => continue,
            };
            if *owner == *no {
                continue;
            }
            let dx = pos.x - npos.x;
            let dy = pos.y - npos.y;
            if dx * dx + dy * dy < COMBAT_RANGE_SQ {
                enemies.push(ne);
            }
        }

        // Write/update NearbyEnemies.
        let has_enemies = !enemies.is_empty();
        if let Ok((nb,)) = world.query_one_mut::<(&mut NearbyEnemies,)>(entity) {
            nb.entities = std::mem::take(&mut enemies);
            nb.initialized = true;
            enemies = Vec::with_capacity(16); // restore capacity
        } else {
            let _ = world.insert(
                entity,
                (NearbyEnemies {
                    entities: enemies.drain(..).collect(),
                    initialized: true,
                },),
            );
            enemies = Vec::with_capacity(16);
        }

        // Set `attacking` flag for movers only.
        if is_moved {
            if let Ok((mut_flags,)) = world.query_one_mut::<(&mut UnitFlags,)>(entity) {
                mut_flags.attacking = has_enemies;
            }
        }
    }
}

