+    #[inline]
+    fn cell_idx(&self, cx: i32, cy: i32) -> Option<usize> {
+        let x = (cx - self.min_x) as isize;
+        let y = (cy - self.min_y) as isize;
+        let w = self.width as isize;
+        if (0..w).contains(&x) && (0..(self.cells.len() as isize / w)).contains(&y) {
+            Some((y * w + x) as usize)
+        } else {
