//! NearbyEnemies — grid-based neighbour rebuild every tick.
//!
//! Uses a coarse spatial grid (cell_size = COMBAT_RANGE = 2.0) so each unit only
//! checks the ~1-5 entities in its 3×3 cell neighbourhood instead of every
//! other unit. No HashMap-based SpatialHash, no incremental maintenance.
//!
//! Pipeline (with TickContext):
//!   1. Use TickContext to get entity→owner mapping (pre-built, no ECS query).
//!   2. Collect positions + moved flags in a minimal ECS query.
//!   3. Build grid index: each cell stores (entity, position, owner_id).
//!   4. For each unit, query 3×3 cell neighbourhood, filter enemies within
//!      COMBAT_RANGE using the owner id (u8 comparison), write NearbyEnemies
//!      and `attacking` flag.
//!
//! Complexity: O(n × c) where c ≈ entities per 3×3 cell neighbourhood.
//! At game scale (500 units on 200×200 grid), c is very small (~2-3), so
//! this is ~150-250 distance checks vs 250,000 for brute-force O(n²).

use crate::game::components::*;
use crate::game::constants::COMBAT_RANGE_SQ;
use crate::game::game::TickContext;
use hecs::Entity;

/// Cell size equals COMBAT_RANGE (sqrt(4.0) = 2.0).
const CELL_SIZE: f32 = 2.0;

/// Data stored per entity in a grid cell.
#[derive(Clone, Copy)]
struct CellEntry {
    entity: Entity,
    pos: UnitPosition,
    owner_id: u8,
}

/// Coarse spatial grid: 1D array of cell buckets.
struct GridIndex {
    cells: Box<[Vec<CellEntry>]>,
    min_x: i32,
    min_y: i32,
    width: usize,
}

impl GridIndex {
    fn build(units: &[(Entity, UnitPosition, u8)]) -> Self {
        let mut min_x = i32::MAX;
        let mut min_y = i32::MAX;
        let mut max_x = i32::MIN;
        let mut max_y = i32::MIN;
        for &(_, pos, _) in units {
            let c = cell_for(pos);
            if c.0 < min_x { min_x = c.0; }
            if c.1 < min_y { min_y = c.1; }
            if c.0 > max_x { max_x = c.0; }
            if c.1 > max_y { max_y = c.1; }
        }
        let width = (max_x - min_x + 2) as usize;
        let height = (max_y - min_y + 2) as usize;
        let total = width * height;

        let mut cells: Vec<Vec<CellEntry>> = vec![Vec::with_capacity(4); total];

        for &(e, pos, oid) in units {
            let c = cell_for(pos);
            let cx = ((c.0 - min_x) as usize).min(width - 1);
            let cy = ((c.1 - min_y) as usize).min(height - 1);
            let idx = cy * width + cx;
            cells[idx].push(CellEntry {
                entity: e,
                pos,
                owner_id: oid,
            });
        }

        Self {
            cells: cells.into_boxed_slice(),
            min_x,
            min_y,
            width,
        }
    }

    #[inline]
    fn cell_idx(&self, cx: i32, cy: i32) -> Option<usize> {
        let x = (cx - self.min_x) as isize;
        let y = (cy - self.min_y) as isize;
        let w = self.width as isize;
        if (0..w).contains(&x) && (0..(self.cells.len() as isize / w)).contains(&y) {
            Some((y * w + x) as usize)
        } else {
            None
        }
    }
}

#[inline]
fn cell_for(pos: UnitPosition) -> (i32, i32) {
    (
        (pos.x / CELL_SIZE).floor() as i32,
        (pos.y / CELL_SIZE).floor() as i32,
    )
}

/// Main entry point — uses TickContext for pre-built entity→owner mapping.
pub fn run(world: &mut hecs::World, ctx: &TickContext) {
    // 1. Collect position + moved flag in a minimal ECS query.
    //    Owner data comes from TickContext (avoids querying UnitOwner + UnitPosition).
    let mut moved_map: std::collections::HashMap<Entity, bool> =
        std::collections::HashMap::with_capacity(600);
    for (entity, flags) in world.query::<(Entity, &UnitFlags)>().iter() {
        moved_map.insert(entity, flags.moved);
    }

    // Build units array from TickContext data.
    // units_by_player gives us entities + positions grouped by player.
    let units: Vec<(Entity, UnitPosition, u8)> = ctx
        .units_by_player
        .iter()
        .flat_map(|(_pid, handles)| {
            handles.iter().filter_map(move |h| {
                let owner_id = *ctx.entity_owner.get(&h.entity)?;
                Some((h.entity, UnitPosition { x: h.pos.0, y: h.pos.1 }, owner_id))
            })
        })
        .collect();

    let n = units.len();
    if n == 0 {
        return;
    }

    // 2. Build grid index.
    let grid = GridIndex::build(&units);

    // Reuse buffer to avoid per-unit allocation.
    let mut enemies = Vec::with_capacity(16);

    // 3. For each unit, query 3×3 neighbourhood and build NearbyEnemies.
    for &(entity, pos, my_owner) in &units {
        let c = cell_for(pos);

        enemies.clear();
        for dx in -1..=1 {
            for dy in -1..=1 {
                if let Some(idx) = grid.cell_idx(c.0 + dx, c.1 + dy) {
                    for entry in &grid.cells[idx] {
                        if entry.entity == entity {
                            continue;
                        }
                        if entry.owner_id == my_owner {
                            continue;
                        }
                        let dx_pos = pos.x - entry.pos.x;
                        let dy_pos = pos.y - entry.pos.y;
                        if dx_pos * dx_pos + dy_pos * dy_pos < COMBAT_RANGE_SQ {
                            enemies.push(entry.entity);
                        }
                    }
                }
            }
        }

        // Write/update NearbyEnemies.
        let has_enemies = !enemies.is_empty();
        if let Ok((nb,)) = world.query_one_mut::<(&mut NearbyEnemies,)>(entity) {
            nb.entities = std::mem::take(&mut enemies);
            nb.initialized = true;
            enemies = Vec::with_capacity(16);
        } else {
            let _ = world.insert(
                entity,
                (NearbyEnemies {
                    entities: enemies.drain(..).collect(),
                    initialized: true,
                },),
            );
            enemies = Vec::with_capacity(16);
        }

        // Set `attacking` flag for movers only.
        if moved_map.get(&entity).copied().unwrap_or(false) {
            if let Ok((mut_flags,)) = world.query_one_mut::<(&mut UnitFlags,)>(entity) {
                mut_flags.attacking = has_enemies;
            }
        }
    }
}

/// Fallback for when TickContext is unavailable (tests, edge cases).
pub fn run_fallback(world: &mut hecs::World) {
    let units: Vec<(Entity, UnitPosition, String, bool)> = world
        .query::<(Entity, &UnitPosition, &UnitOwner, &UnitFlags)>()
        .iter()
        .map(|(e, pos, owner, flags)| {
            (e, *pos, owner.player_id.clone(), flags.moved)
        })
        .collect();

    let n = units.len();
    if n == 0 {
        return;
    }

    let owner_ids: Vec<usize> = {
        let mut owner_map: std::collections::HashMap<&str, usize> =
            std::collections::HashMap::with_capacity(16);
        let mut next_id: usize = 0;
        units
            .iter()
            .map(|(_, _, ref pid, _)| {
                *owner_map.entry(pid.as_str()).or_insert_with(|| {
                    let id = next_id;
                    next_id += 1;
                    id
                })
            })
            .collect()
    };

    // Build grid with usize owner IDs for fallback.
    let grid: GridIndexFb = GridIndexFb::build(&units, &owner_ids);

    let mut enemies = Vec::with_capacity(16);

    for (my_idx, &(entity, pos, _, is_moved)) in units.iter().enumerate() {
        let my_owner = owner_ids[my_idx];
        let c = cell_for(pos);

        enemies.clear();
        for dx in -1..=1 {
            for dy in -1..=1 {
                if let Some(idx) = grid.cell_idx(c.0 + dx, c.1 + dy) {
                    for entry in &grid.cells[idx] {
                        if entry.entity == entity {
                            continue;
                        }
                        if entry.owner_id == my_owner {
                            continue;
                        }
                        let dx_pos = pos.x - entry.pos.x;
                        let dy_pos = pos.y - entry.pos.y;
                        if dx_pos * dx_pos + dy_pos * dy_pos < COMBAT_RANGE_SQ {
                            enemies.push(entry.entity);
                        }
                    }
                }
            }
        }

        let has_enemies = !enemies.is_empty();
        if let Ok((nb,)) = world.query_one_mut::<(&mut NearbyEnemies,)>(entity) {
            nb.entities = std::mem::take(&mut enemies);
            nb.initialized = true;
            enemies = Vec::with_capacity(16);
        } else {
            let _ = world.insert(
                entity,
                (NearbyEnemies {
                    entities: enemies.drain(..).collect(),
                    initialized: true,
                },),
            );
            enemies = Vec::with_capacity(16);
        }

        if is_moved {
            if let Ok((mut_flags,)) = world.query_one_mut::<(&mut UnitFlags,)>(entity) {
                mut_flags.attacking = has_enemies;
            }
        }
    }
}

/// Fallback grid index (uses usize owner IDs instead of u8).
struct GridIndexFb {
    cells: Box<[Vec<CellEntryFb>]>,
    min_x: i32,
    min_y: i32,
    width: usize,
}

#[derive(Clone, Copy)]
struct CellEntryFb {
    entity: Entity,
    pos: UnitPosition,
    owner_id: usize,
}

impl GridIndexFb {
    fn build(units: &[(Entity, UnitPosition, String, bool)], owner_ids: &[usize]) -> Self {
        let mut min_x = i32::MAX;
        let mut min_y = i32::MAX;
        let mut max_x = i32::MIN;
        let mut max_y = i32::MIN;
        for &(_, pos, _, _) in units {
            let c = cell_for(pos);
            if c.0 < min_x { min_x = c.0; }
            if c.1 < min_y { min_y = c.1; }
            if c.0 > max_x { max_x = c.0; }
            if c.1 > max_y { max_y = c.1; }
        }
        let width = (max_x - min_x + 2) as usize;
        let height = (max_y - min_y + 2) as usize;
        let total = width * height;

        let mut cells: Vec<Vec<CellEntryFb>> = vec![Vec::with_capacity(4); total];

        for (i, &(e, pos, _, _)) in units.iter().enumerate() {
            let c = cell_for(pos);
            let cx = ((c.0 - min_x) as usize).min(width - 1);
            let cy = ((c.1 - min_y) as usize).min(height - 1);
            let idx = cy * width + cx;
            cells[idx].push(CellEntryFb {
                entity: e,
                pos,
                owner_id: owner_ids[i],
            });
        }

        Self {
            cells: cells.into_boxed_slice(),
            min_x,
            min_y,
            width,
        }
    }

    #[inline]
    fn cell_idx(&self, cx: i32, cy: i32) -> Option<usize> {
        let x = (cx - self.min_x) as isize;
        let y = (cy - self.min_y) as isize;
        let w = self.width as isize;
        if (0..w).contains(&x) && (0..(self.cells.len() as isize / w)).contains(&y) {
            Some((y * w + x) as usize)
        } else {
            None
        }
    }
}

