/// Pre-built fixture for nearby_enemies benchmarks.
struct NearbyEnemiesFixture {
    world: World,
    ctx: crate::game::game::TickContext,
}

impl NearbyEnemiesFixture {
    fn new_movers(
        width: u32,
        height: u32,
        num_players: usize,
        unit_type: &UnitType,
        count: usize,
    ) -> Self {
        let (mut world, world_entity) = make_world(width, height, num_players);
        let _ = spawn_n_units(&mut world, world_entity, unit_type, count);
        let ctx = crate::game::game::TickContext::build(&world, world_entity)
            .expect("TickContext build failed");
        Self {
            world,
            ctx,
        }
    }
}

