/// Entity+position handle for unit grouping. Snapshot taken at tick start;
/// systems that need fresh component data (e.g. supply, which runs after
/// combat) do their own bulk query instead of per-entity world lookups.
#[derive(Debug, Clone, Copy)]
pub struct UnitHandle {
    pub entity: hecs::Entity,
    pub pos: (f32, f32),
}

/// Flat unit record with everything needed by spatial/adjacency systems.
/// Built once per tick in TickContext to avoid per-system ECS queries.
#[derive(Debug, Clone, Copy)]
pub struct UnitData {
    pub entity: hecs::Entity,
    pub pos: UnitPosition,
    pub flags: UnitFlags,
    pub owner_id: u8,
}

#[derive(Debug)]
pub struct TickContext {
    /// The world entity handle (needed for world_data_mut writes)
    pub world_entity: hecs::Entity,
    /// Cities snapshot — small (~20 entries), cloned once per tick
    pub cities: Vec<crate::game::economy::City>,
    /// Economy funds snapshot
    pub funds: HashMap<String, u32>,
    /// Map dimensions (cached to avoid per-system world borrows)
    pub width: u32,
    pub height: u32,
    /// Entity+position handles grouped by player ID (for player-scoped queries)
    pub units_by_player: HashMap<String, Vec<UnitHandle>>,
    /// Flat unit array with inline owner IDs and full UnitFlags.
    /// Enables zero-ECS-query systems (nearby_enemies, etc).
    pub units: Vec<UnitData>,
}

