// Single pass: group entities+positions by player + build flat unit array
let mut units_by_player: HashMap<String, Vec<UnitHandle>> = HashMap::new();
let mut units: Vec<UnitData> = Vec::new();
let mut owner_names: Vec<String> = Vec::new();

for (entity, owner, pos, flags) in world.query::<(Entity, &UnitOwner, &UnitPosition, &UnitFlags)>().iter() {
    let owner_idx = {
        if let Some(idx) = owner_names.iter().position(|n| n == &owner.player_id) {
            idx as u8
        } else {
            let idx = owner_names.len() as u8;
            owner_names.push(owner.player_id.clone());
            idx
        }
    };
    units_by_player
        .entry(owner.player_id.clone())
        .or_default()
        .push(UnitHandle {
            entity,
            pos: (*pos).as_tuple(),
        });
    units.push(UnitData {
        entity,
        pos: *pos,
        flags: *flags,
        owner_id: owner_idx,
    });
}

Some(Self {
    world_entity,
    cities,
    funds,
    width,
    height,
    units_by_player,
    units,
})

